{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.B2C_NS_DAILY AS WITH params AS ( SELECT CAST(CONVERT_TIMEZONE(\'America/Los_Angeles\',\'Asia/Kolkata\', CURRENT_TIMESTAMP) AS DATE) AS IST_TODAY ), base AS ( SELECT CAST(TAT AS DATE) AS REPORT_DATE, UPPER(TRIM(WAREHOUSE_NAME)) AS WAREHOUSE_NAME, UPPER(TRIM(MARKETPLACE_MAPPED)) AS MARKETPLACE_MAPPED, UPPER(TRIM(SLA_STATUS)) AS SLA_STATUS, LOWER(IFNULL(CANCELLATION_REASON,\'\')) AS CANCELLATION_REASON, SALEORDERITEMCODE, ORDER_TIMESTAMP, UC_CREATED, DISPATCHED_TIMESTAMP, PACKED_TIME FROM SNITCH_DB.MAPLEMONK.WAREHOUSE_SLA_PERFORMANCE WHERE UPPER(IFNULL(WAREHOUSE_NAME,\'\')) IN (\'SAPL-WH1\',\'SAPL-WH2\',\'SAPL-NORTH-TAURU\') AND UPPER(IFNULL(MARKETPLACE_MAPPED,\'\')) IN ( \'SHOPIFY\',\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\' ) AND EXCHANGE_FLAG IS NULL AND ERROR IS NULL ), daily AS ( SELECT REPORT_DATE, COUNT(DISTINCT SALEORDERITEMCODE) AS FORWARD_ITEMS, COUNT(DISTINCT CASE WHEN NOT (CANCELLATION_REASON LIKE ANY (\'%cust%\',\'%sell%\',\'%cx%\',\'%other%\',\'%panel%\',\'%test%\',\'%mer%\')) THEN SALEORDERITEMCODE END ) AS FULFILL_NUM, COUNT(DISTINCT SALEORDERITEMCODE) AS FULFILL_DEN, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED IN (\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\') AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_MP_NUM, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED IN (\'AMAZON\',\'FLIPKART\',\'MYNTRA\',\'AJIO\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\') AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_MP_DEN, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_OVERALL, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_WH1, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_WH2, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND ORDER_TIMESTAMP IS NOT NULL AND DISPATCHED_TIMESTAMP IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, DISPATCHED_TIMESTAMP) END) AS O2M_SAPL_NORTH_TAURU, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_OVERALL, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_WH1, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_WH2, AVG(CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND ORDER_TIMESTAMP IS NOT NULL AND PACKED_TIME IS NOT NULL THEN DATEDIFF(\'HOUR\', ORDER_TIMESTAMP, PACKED_TIME) END) AS O2P_SAPL_NORTH_TAURU, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_WH1, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH1\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_WH1, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_WH2, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-WH2\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_WH2, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND SLA_STATUS = \'WITHIN SLA\' THEN SALEORDERITEMCODE END ) AS SLA_SF_NUM_SAPL_NORTH_TAURU, COUNT(DISTINCT CASE WHEN MARKETPLACE_MAPPED = \'SHOPIFY\' AND WAREHOUSE_NAME = \'SAPL-NORTH-TAURU\' AND SLA_STATUS <> \'CANCELLED\' THEN SALEORDERITEMCODE END ) AS SLA_SF_DEN_SAPL_NORTH_TAURU FROM base GROUP BY REPORT_DATE ) SELECT REPORT_DATE, FORWARD_ITEMS, ROUND((FULFILL_NUM / NULLIF(FULFILL_DEN,0)) * 100, 2) AS FULFILLMENT_PCT, ROUND((SLA_SF_NUM / NULLIF(SLA_SF_DEN,0)) * 100, 2) AS SLA_ADHERENCE_SF_PCT, ROUND((SLA_MP_NUM / NULLIF(SLA_MP_DEN,0)) * 100, 2) AS SLA_ADHERENCE_MP_PCT, ROUND(O2M_OVERALL, 2) AS O2M_OVERALL, ROUND(O2M_SAPL_WH1, 2) AS O2M_SAPL_WH1, ROUND(O2M_SAPL_WH2, 2) AS O2M_SAPL_WH2, ROUND(O2M_SAPL_NORTH_TAURU, 2) AS O2M_SAPL_NORTH_TAURU, ROUND(O2P_OVERALL, 2) AS O2P_OVERALL, ROUND(O2P_SAPL_WH1, 2) AS O2P_SAPL_WH1, ROUND(O2P_SAPL_WH2, 2) AS O2P_SAPL_WH2, ROUND(O2P_SAPL_NORTH_TAURU, 2) AS O2P_SAPL_NORTH_TAURU, ROUND((SLA_SF_NUM_SAPL_WH1 / NULLIF(SLA_SF_DEN_SAPL_WH1,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_WH1_PCT, ROUND((SLA_SF_NUM_SAPL_WH2 / NULLIF(SLA_SF_DEN_SAPL_WH2,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_WH2_PCT, ROUND((SLA_SF_NUM_SAPL_NORTH_TAURU / NULLIF(SLA_SF_DEN_SAPL_NORTH_TAURU,0)) * 100, 2) AS SLA_ADHERENCE_SF_SAPL_NORTH_TAURU_PCT FROM daily;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            